from PySide6 import QtCore, QtWidgets
from PySide6.QtCore import Qt
from PySide6.QtGui import QIcon
from PySide6.QtWidgets import QDialog

from videotrans.configure.config import tr,ROOT_DIR
from videotrans.configure.constants import ELEVENLABS_TTS_MODELS, FISHAUDIO_TTS_MODELS
from videotrans.util.help_misc import open_url


class Ui_fishaudio(QDialog):
    def __init__(self):
        super().__init__()
        self.setWindowIcon(QIcon(f"{ROOT_DIR}/videotrans/styles/icon.ico"))
        self.setupUi(self)
    def setupUi(self, form):
        self.has_done = False
        form.setObjectName("form")
        form.resize(800, 300)

        self.verticalLayout = QtWidgets.QVBoxLayout(form)
        self.verticalLayout.setObjectName("verticalLayout")

        self.formLayout_2 = QtWidgets.QHBoxLayout()
        self.formLayout_3 = QtWidgets.QHBoxLayout()

        self.label = QtWidgets.QLabel()
        self.label.setMinimumSize(QtCore.QSize(100, 35))
        self.label.setObjectName("label")

        self.fishaudio_key = QtWidgets.QLineEdit()
        self.fishaudio_key.setMinimumSize(QtCore.QSize(210, 35))
        self.fishaudio_key.setObjectName("fishaudio_key")

        self.formLayout_2.addWidget(self.label)
        self.formLayout_2.addWidget(self.fishaudio_key)

        self.label2 = QtWidgets.QLabel()
        self.label2.setMinimumSize(QtCore.QSize(100, 35))
        self.label2.setObjectName("label2")

        self.fishaudio_model = QtWidgets.QComboBox()
        self.fishaudio_model.setMinimumSize(QtCore.QSize(210, 35))
        self.fishaudio_model.setObjectName("fishaudio_model")
        self.fishaudio_model.addItems(FISHAUDIO_TTS_MODELS.split(','))

        self.formLayout_3.addWidget(self.label2)
        self.formLayout_3.addWidget(self.fishaudio_model)

        self.verticalLayout.addLayout(self.formLayout_2)
        self.verticalLayout.addLayout(self.formLayout_3)

        self.set = QtWidgets.QPushButton()
        self.set.setMinimumSize(QtCore.QSize(0, 35))
        self.set.setObjectName("set")

        self.test = QtWidgets.QPushButton()
        self.test.setMinimumSize(QtCore.QSize(0, 35))
        self.test.setObjectName("test")

        self.update_btn = QtWidgets.QPushButton()
        self.update_btn.setMinimumSize(QtCore.QSize(0, 35))
        self.update_btn.setObjectName("update_btn")
        self.update_btn.setText(tr("Update my voice"))

        tips=QtWidgets.QLabel(tr("fishaudio update role tips"))
        tips.setWordWrap(True)
        tips.setStyleSheet("color:#aaaaaa")
        self.verticalLayout.addWidget(tips)

        help_btn = QtWidgets.QPushButton()
        help_btn.setMinimumSize(QtCore.QSize(0, 35))
        help_btn.setStyleSheet("background-color: rgba(255, 255, 255,0)")
        help_btn.setObjectName("help_btn")
        help_btn.setCursor(Qt.PointingHandCursor)
        help_btn.setText(tr("Fill out the tutorial"))
        help_btn.clicked.connect(lambda: open_url(url='https://pyvideotrans.com/fishaudioapi'))

        hv = QtWidgets.QHBoxLayout()
        hv.addWidget(self.set)
        hv.addWidget(self.test)
        hv.addWidget(self.update_btn)
        hv.addWidget(help_btn)

        self.verticalLayout.addLayout(hv)

        self.retranslateUi(form)
        QtCore.QMetaObject.connectSlotsByName(form)

    def retranslateUi(self, form):
        form.setWindowTitle("Fish.audio")
        self.label2.setText(tr('From  Text  Into  Speech')+tr("Model"))
        self.label.setText(tr("SK"))
        self.set.setText(tr("Save"))
        self.test.setText(tr("Test"))
